[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ProjectRoot,[Parameter(Mandatory=$true)][string]$PacketPath)
$ErrorActionPreference='Stop';$root=(Resolve-Path -LiteralPath $ProjectRoot).Path;if([IO.Path]::IsPathRooted($PacketPath)){throw 'PacketPath must be project-relative.'};$rel=$PacketPath.Replace('\','/').Trim();if($rel.Contains('..')-or $rel -notmatch '^ES/Output/.+\.json$'){throw 'PacketPath must remain under ES/Output.'};$full=Join-Path $root ($rel.Replace('/',[IO.Path]::DirectorySeparatorChar));if(-not(Test-Path -LiteralPath $full -PathType Leaf)){throw "ESTest launch packet missing: $rel"}
$p=([Text.UTF8Encoding]::new($false,$true).GetString([IO.File]::ReadAllBytes($full))|ConvertFrom-Json);foreach($f in @('schemaVersion','projectPath','mode','resultsPath','evidenceLayer')){if([string]::IsNullOrWhiteSpace([string]$p.$f)){throw "ESTest packet missing ${f}."}};if([string]$p.schemaVersion -ne '1'-or [string]$p.mode -notin @('EditModeTests','PlayModeTests','Compile')){throw 'ESTest packet schema or mode invalid.'};if([IO.Path]::IsPathRooted([string]$p.projectPath)-or [IO.Path]::IsPathRooted([string]$p.resultsPath)){throw 'ESTest packet paths must be relative.'};if([string]$p.evidenceLayer -notin @('unity-test-runner','unity-editor-compile')){throw 'ESTest evidence layer is invalid.'}
Write-Output "PASS: ESTest launch packet is bounded: $rel"
